using System.Threading.Tasks;
using Altinn.App.Core.Features;
using Altinn.Platform.Storage.Interface.Models;

namespace Altinn.App.Logic.Fagsystem;

public class VarsleVedInnsending : IProcessTaskEnd
{
    private readonly IFagsystemVarsler _fagsystemVarsler;

    public VarsleVedInnsending(IFagsystemVarsler fagsystemVarsler)
    {
        _fagsystemVarsler = fagsystemVarsler;
    }

    public async Task End(string taskId, Instance instance)
    {
        await _fagsystemVarsler.VarsleNySoknad(instance);
    }
}

using Altinn.App.Core.Features;

namespace Altinn.App.Logic.Fagsystem;

public class VarsleVedInnsending : IOnTaskEndingHandler
{
    private readonly IFagsystemVarsler _fagsystemVarsler;

    public VarsleVedInnsending(IFagsystemVarsler fagsystemVarsler)
    {
        _fagsystemVarsler = fagsystemVarsler;
    }

    public bool ShouldRunForTask(string taskId) => taskId == "Task_1";

    public async Task<HandlerResult> Execute(OnTaskEndingContext context)
    {
        await _fagsystemVarsler.VarsleNySoknad(context.InstanceDataMutator.Instance);
        return HandlerResult.Success();
    }
}

